SELECT DISTINCT to_team FROM player_transfers
WHERE to_team ILIKE ANY (ARRAY['%Liverpool%','%Chelsea%','%Man%','%Arsenal%','%Tottenham%','%Spurs%','%Newcastle%','%Aston%','%West Ham%','%Brighton%','%Everton%','%Leicester%','%Wolves%','%Nottingham%','%Forest%','%Fulham%','%Brentford%','%Bournemouth%','%Crystal%'])
ORDER BY to_team;
